import { SessionPartTrackerEvents, SessionTrackerEvents } from '../../constants/sessions.js';
import { infoLogger } from '../../modules/logger.js';
import { calculateDurationInSeconds } from './utils.js';

class SessionTrackerService{start(){if(!this.startTime){this.startTime=new Date().valueOf();this.lastActivityTime=this.startTime;this.partTracker.start();this.log("Start session");}return this.session}continue(t){if(this.sessionUuid!==t.sessionUuid){this.log(`WARNING! Requested to start session with different id: ${t.sessionUuid}`);}if(!this.startTime){this.startTime=t.start;this.lastActivityTime=t.lastActivity;this.partTracker.start();this.log("Continue session");}}destroy(){this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerEndEvent].remove(this.onPartEnd);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerPartGoing].remove(this.updateSessionLastActiveTime);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerStartEvent].remove(this.onPartStart);const s=new Date().valueOf();const i=this.partTracker.destroy();return [this.endSession(s),i]}get session(){return {sessionUuid:this.sessionUuid,lastActivity:this.endTime||Number(this.lastActivityTime),start:Number(this.startTime),appId:this.appId,...this.endTime?{duration:calculateDurationInSeconds(Number(this.startTime),this.endTime)}:{}}}endSession(t){if(!this.startTime){return}this.endTime=t;const s=this.session;this.log("End session",s.duration);return s}log(t,...s){infoLogger(`[SessionTrackerService][${this.sessionUuid}] ${t}`,...s);}constructor(i,e,r,o){this.onPartEnd=t=>{this.lastActivityTime=t.end;this.eventHooks[SessionTrackerEvents.SessionPartEnd].fire(t);};this.updateSessionLastActiveTime=t=>{this.lastActivityTime=t.lastActivity||new Date().valueOf();this.eventHooks[SessionTrackerEvents.SessionGoing].fire(t);};this.onPartStart=()=>{this.eventHooks[SessionTrackerEvents.SessionPartStart].fire();};this.sessionUuid=e;this.appId=i;this.partTracker=r;this.eventHooks=o;this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerEndEvent].add(this.onPartEnd);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerPartGoing].add(this.updateSessionLastActiveTime);this.eventHooks[SessionPartTrackerEvents.SessionPartTrackerStartEvent].add(this.onPartStart);}}

export { SessionTrackerService };
